const input = $('Find Prospects Webhook').first().json.body || {};
const g = $input.first().json;

if (!g || !g.boundingbox) {
  throw new Error('City/region not found by Nominatim');
}

const bbox = g.boundingbox;
const south = Number(bbox[0]);
const north = Number(bbox[1]);
const west = Number(bbox[2]);
const east = Number(bbox[3]);

const niche = String(input.niche || '').trim();
const limit = Math.max(1, Math.min(25, Number(input.limit || 10)));

const nicheMap = {
  remodeling: ['remodel','renovat','construction','contractor','builder','carpenter'],
  roofing: ['roof','roofer'],
  painting: ['paint','painter'],
  electrical: ['electric','electrician'],
  plumbing: ['plumb','plumber'],
  landscaping: ['landscap','garden','lawn'],
  cleaning: ['clean','janitor']
};

const key = niche.toLowerCase();
const tokens = nicheMap[key] || [key].filter(Boolean);
const regex = tokens.length ? tokens.join('|') : 'construction|contractor|builder';

let blocks = [];
if (key === 'remodeling') {
  blocks = [
    `nwr["office"="construction_company"](${south},${west},${north},${east});`,
    `nwr["craft"="builder"](${south},${west},${north},${east});`,
    `nwr["craft"="carpenter"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else if (key === 'roofing') {
  blocks = [
    `nwr["craft"="roofer"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else if (key === 'painting') {
  blocks = [
    `nwr["craft"="painter"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else if (key === 'electrical') {
  blocks = [
    `nwr["craft"="electrician"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else if (key === 'plumbing') {
  blocks = [
    `nwr["craft"="plumber"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else if (key === 'landscaping') {
  blocks = [
    `nwr["craft"="gardener"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else if (key === 'cleaning') {
  blocks = [
    `nwr["office"="cleaning"](${south},${west},${north},${east});`,
    `nwr["name"~"${regex}",i](${south},${west},${north},${east});`
  ];
} else {
  blocks = [`nwr["name"~"${regex}",i](${south},${west},${north},${east});`];
}

const q = `[out:json][timeout:25];
(
  ${blocks.join('\n  ')}
);
out center tags ${Math.max(limit * 5, 50)};`;

return [{
  json: {
    ...input,
    niche_key: key,
    niche_tokens: tokens,
    limit,
    bbox: {south, north, west, east},
    overpassQuery: q
  }
}];

const input = $('Build Overpass Query').first().json;
const data = $input.first().json || {};
const elements = Array.isArray(data.elements) ? data.elements : [];

const clean = v => String(v || '').trim();
const first = (...vals) => vals.map(clean).find(Boolean) || '';
const norm = s => clean(s).toLowerCase();
const tokens = Array.isArray(input.niche_tokens) ? input.niche_tokens : [];

const normalizePhone = (v) => clean(v).replace(/\s+/g, ' ');
const normalizeWebsite = (v) => {
  const s = clean(v);
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s;
  return 'https://' + s.replace(/^\/+/, '');
};

const seen = new Set();
const out = [];

for (const el of elements) {
  const t = el.tags || {};
  const company = first(t.name, t.operator, t.brand);
  if (!company) continue;

  const haystack = norm([
    company,
    t.office,
    t.craft,
    t.shop,
    t.description,
    t.operator,
    t.brand
  ].filter(Boolean).join(' '));

  const nicheMatch = tokens.length === 0 || tokens.some(tok => haystack.includes(norm(tok)));

  const explicitTradeMatch =
    (input.niche_key === 'remodeling' && (
      t.office === 'construction_company' ||
      t.craft === 'builder' ||
      t.craft === 'carpenter'
    )) ||
    (input.niche_key === 'roofing' && t.craft === 'roofer') ||
    (input.niche_key === 'painting' && t.craft === 'painter') ||
    (input.niche_key === 'electrical' && t.craft === 'electrician') ||
    (input.niche_key === 'plumbing' && t.craft === 'plumber') ||
    (input.niche_key === 'landscaping' && t.craft === 'gardener');

  if (!nicheMatch && !explicitTradeMatch) continue;

  const website = normalizeWebsite(first(t['contact:website'], t.website, t.url));
  const phone = normalizePhone(first(t['contact:phone'], t.phone, t['contact:mobile'], t.mobile));
  const email = first(t['contact:email'], t.email);
  const facebook = first(t['contact:facebook'], t.facebook);
  const instagram = first(t['contact:instagram'], t.instagram);
  const wikidata = first(t.wikidata, t['brand:wikidata']);
  const operator = first(t.operator);
  const brand = first(t.brand);

  const lat = el.lat ?? el.center?.lat ?? null;
  const lon = el.lon ?? el.center?.lon ?? null;

  const street = first(t['addr:street']);
  const house = first(t['addr:housenumber']);
  const postcode = first(t['addr:postcode']);
  const osmCity = first(t['addr:city'], t['addr:town'], t['addr:village'], input.city);
  const country = first(t['addr:country'], input.country);

  const addressParts = [];
  if (house || street) addressParts.push([house, street].filter(Boolean).join(' '));
  if (osmCity) addressParts.push(osmCity);
  if (postcode) addressParts.push(postcode);
  if (country) addressParts.push(country);
  const address = addressParts.join(', ');

  let score = 30;
  score += explicitTradeMatch ? 25 : 10;
  if (website) score += 15;
  if (phone) score += 10;
  if (email) score += 10;
  if (wikidata) score += 5;
  if (facebook || instagram) score += 5;

  const issue = website
    ? 'Website listed in OpenStreetMap; verify quality before outreach'
    : 'No website listed in OpenStreetMap';

  const id = `osm-${el.type}-${el.id}`;

  const dedupeKey = email
    ? `email:${email.toLowerCase()}`
    : phone
      ? `phone:${phone.replace(/\D/g, '')}`
      : `company:${company.toLowerCase()}|city:${osmCity.toLowerCase()}`;

  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);

  out.push({
    json: {
      id,
      osm_type: el.type,
      osm_id: String(el.id),
      company,
      niche: input.niche || '',
      country,
      city: osmCity,
      email,
      phone,
      website,
      contact_website: first(t['contact:website']),
      contact_phone: first(t['contact:phone']),
      contact_email: first(t['contact:email']),
      wikidata,
      brand,
      operator,
      facebook,
      instagram,
      whatsapp: 'Unknown',
      status: 'New',
      verification_status: 'Needs verification',
      safe_to_outreach: false,
      niche_match: true,
      issue,
      score: Math.min(score, 100),
      source: 'OpenStreetMap',
      source_tags: {
        office: first(t.office),
        craft: first(t.craft),
        description: first(t.description),
        website: first(t.website),
        contact_website: first(t['contact:website']),
        phone: first(t.phone),
        contact_phone: first(t['contact:phone']),
        email: first(t.email),
        contact_email: first(t['contact:email']),
        wikidata,
        brand,
        operator,
        facebook,
        instagram
      },
      address,
      lat,
      lon,
      enrichment_payload: {
        company,
        city: osmCity,
        country,
        niche: input.niche || '',
        phone,
        email,
        website,
        wikidata,
        source: 'OpenStreetMap',
        id
      }
    }
  });

  if (out.length >= input.limit) break;
}

return out.length
  ? out
  : [{json:{prospects:[], empty:true, message:'No niche-matched prospects found in OpenStreetMap for this search.'}}];

const items = $input.all();

if (items.length === 1 && items[0].json.empty) {
  return [{json:{prospects:[], count:0, message:items[0].json.message}}];
}

return [{
  json: {
    prospects: items.map(i => i.json),
    count: items.length
  }
}];
